package com.rohit.inventory.entity; import jakarta.persistence.*; import java.util.UUID; @Entity @Table(name="notification_preferences",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","notification_type"})) public class NotificationPreference extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Column(name="notification_type",nullable=false) private String notificationType; @Column(nullable=false) private boolean enabled=true; public User getUser(){return user;} public String getNotificationType(){return notificationType;} public boolean isEnabled(){return enabled;} public void setUser(User v){user=v;} public void setNotificationType(String v){notificationType=v;} public void setEnabled(boolean v){enabled=v;} }
